<!DOCTYPE html></!DOCTYPE>
<html>
<head>
    <meta charset="UTF-8"></meta>
    <meta name="viewport" content="width=device-width, initial-scale=1.0"></meta>
    <title>文本1</title>
    <style>
        :root {
            --card-background: #f8f4e6; 
            --card-border: #d1c7b7; 
            --text-color: #5a4a3a; 
            --header-color: #7b6b5a; 
            --section-header-bg: #eee8d5; 
            --section-header-hover: #e0d9c6;
            --progress-bg: #e0e0e0; 
            --affection-color: #ffb6c1; 
            --trust-color: #a2d9ce; 
            --decoration-color: #c0a080; 
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; 
            margin: 0; 
            padding: 0;
        }

        .status-card {
            width: 95%;
            max-width: 300px; 
            background: var(--card-background);
            border: 1px solid var(--card-border);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 2px 2px 8px rgba(0, 0, 0, 0.1);
            color: var(--text-color);
            margin: 0 auto; 
        }

        .card-header {
            background: linear-gradient(to right, var(--section-header-bg), rgba(238, 232, 213, 0.5));
            padding: 8px 15px;
            border-bottom: 1px solid var(--card-border);
            position: relative;
            text-align: center;
            cursor: pointer; 
            user-select: none; 
        }

        .card-header h2 {
            margin: 0;
            font-size: 1.1em;
            color: var(--header-color);
            position: relative;
            display: inline-block;
        }


        .card-header h2::before,
        .card-header h2::after {
            content: '✦'; 
            color: var(--decoration-color);
            font-size: 0.8em;
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
        }

        .card-header h2::before {
            left: -1.2em;
        }

        .card-header h2::after {
            right: -1.2em;
        }

        .card-body {

            padding: 0;
             border-bottom: 1px dashed var(--card-border); 
        }



        .section-content {
            max-height: 0; 
            overflow: hidden;
            transition: max-height 0.3s ease-out, padding-top 0.3s ease-out, padding-bottom 0.3s ease-out; 
            padding-top: 0; 
            padding-bottom: 0;
             padding-left: 15px; 
             padding-right: 15px; 
        }

        .section-content.expanded {
            max-height: 500px; 
            padding-top: 10px; 
            padding-bottom: 10px; 

        }


        .property {
            display: flex;
            align-items: center;
            margin-bottom: 12px; 
            font-size: 0.9em;
            flex-wrap: wrap; 
        }

        .property:last-child {
            margin-bottom: 0; 
        }

        .property-name {
            font-weight: bold;
            margin-right: 10px;
            min-width: 60px; 
        }

         .property-value-container {
             flex-grow: 1; 
             display: flex;
             flex-direction: column; 
             align-items: flex-start;
         }

        .value-main {
            font-weight: normal; 
            white-space: nowrap; 
        }

        .value-description {
             font-size: 0.8em; 
             color: rgba(90, 74, 58, 0.7); 
             margin-top: 2px;
              max-width: 100%; 
              white-space: normal;
              word-break: break-word;
        }

        .progress-bar-container {
            width: 100%; 
            height: 6px; 
            background-color: var(--progress-bg);
            border-radius: 3px;
            margin-top: 4px; 
            overflow: hidden; 
             box-sizing: border-box; 
        }

        .progress-bar-value {
            height: 100%;
            width: 0%; 
            background-color: var(--accent-highlight); 
            transition: width 0.5s ease-in-out; 
            border-radius: 3px;
        }


        .status-card::after {
            content: '✧'; 
            display: block;
            text-align: center;
            color: var(--decoration-color);
            margin-top: -5px; 
            font-size: 1em;
             margin-bottom: 5px;
        }

    </style>
</head>
<body>
<div class="status-card" id="status-card">
    <div class="card-header" id="card-header-toggle">
        <h2>文本1</h2>
    </div>

    <div class="card-body">
        <div class="section-content" id="jingxi-secrets-content">
             </!-->
            <div class="property">
                <div class="property-name">文本2</div>
                <div class="property-value-container">
                     <span class="value-main" id="jingxi-affection">N/A</span>
                     <span class="value-description" id="jingxi-affection-desc"></span>
                </div>
                 <div class="progress-bar-container">
                    <div id="jingxi-affection-bar" class="progress-bar-value" style="width: 0%;"></div>
                </div>
            </div>
             </!-->
            <div class="property">
                <div class="property-name">文本3</div>
                 <div class="property-value-container">
                     <span class="value-main" id="jingxi-trust">N/A</span>
                     <span class="value-description" id="jingxi-trust-desc"></span>
                 </div>
                 <div class="progress-bar-container">
                    <div id="jingxi-trust-bar" class="progress-bar-value" style="width: 0%;"></div>
                </div>
            </div>
        </div>
    </div>
</div>

<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 if (typeof actualValue === 'boolean') {
                     return actualValue;
                 }
                 return String(actualValue);
            } else {
                return defaultValue;
            }
        }
         if (typeof current === 'boolean') {
             return current;
         }
        return String(current);
    }


     function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) {
            return;
        }

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";

        const descriptionMatch = String(fullDisplayString).match(/\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
            descriptionText = descriptionMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim();
        }

        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
         if (valueMatch && !isNaN(parseFloat(valueMatch[1]))) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : fullDisplayString.trim();
         } else if (!isNaN(parseFloat(fullDisplayString))) {
             numericValue = parseFloat(fullDisplayString);
             valueMainDisplay.innerText = fullDisplayString;
         }
         else {
             if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                  numericValue = rawValueFromCharacterData[0];
                 valueMainDisplay.innerText = String(numericValue);
              } else if (typeof rawValueFromCharacterData === 'number' || typeof rawValueFromCharacterData === 'string') {
                  valueMainDisplay.innerText = String(rawValueFromCharacterData);
              }
             else {
                 valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
             }
             numericValue = min;
         }


        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;


             const finalWidth = `${Math.max(0, Math.min(100, percentage))}%`;
             progressBar.style.width = finalWidth; 

            if(color) {
                progressBar.style.backgroundColor = color;
            } else {
                progressBar.style.backgroundColor = 'var(--accent-highlight)';
            }
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {

                 const statusCard = document.getElementById('status-card');
                 if(statusCard) statusCard.innerHTML = "<p style='color:red; padding:10px;'>文本4 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 const statusCard = document.getElementById('status-card');
                 if(statusCard) statusCard.innerHTML = "<p style='color:red; padding:10px;'>文本4 (characterData missing)</p>";
                 return;
            }

            const characterKey = "文本5"; 

            if (characterData.hasOwnProperty(characterKey)) {
                updateProgressBar(
                    'jingxi-affection-bar',
                    'jingxi-affection',
                    'jingxi-affection-desc',
                    SafeGetValue(characterData, `${characterKey}.文本2`),
                    0,
                    100,
                    'var(--affection-color)'
                );

                updateProgressBar(
                    'jingxi-trust-bar',
                    'jingxi-trust',
                    'jingxi-trust-desc',
                    SafeGetValue(characterData, `${characterKey}.文本3`),
                    0,
                    100,
                    'var(--trust-color)'
                );
            } else {

                 const affectionMain = document.getElementById('jingxi-affection');
                 const affectionDesc = document.getElementById('jingxi-affection-desc');
                 const trustMain = document.getElementById('jingxi-trust');
                 const trustDesc = document.getElementById('jingxi-trust-desc');

                 if(affectionMain) affectionMain.innerText = 'N/A';
                 if(affectionDesc) affectionDesc.innerText = '(文本6)';
                 if(trustMain) trustMain.innerText = 'N/A';
                 if(trustDesc) trustDesc.innerText = '(文本6)';

                 const affectionBar = document.getElementById('jingxi-affection-bar');
                 if (affectionBar) affectionBar.style.width = '0%';
                 const trustBar = document.getElementById('jingxi-trust-bar');
                 if (trustBar) trustBar.style.width = '0%';

                 const contentDiv = document.getElementById('jingxi-secrets-content');
                 if (contentDiv) {
                     contentDiv.innerHTML = '<p style="color: rgba(90, 74, 58, 0.7); font-size: 0.9em; text-align: center;">文本7</p>';

                     if (!contentDiv.classList.contains('expanded')) {


                         const header = document.getElementById('card-header-toggle');
                          if (header) {
                              header.querySelector('h2').innerText = '文本8 (文本9)'; 
                          }
                     }
                 }
            }
        } catch (error) {

             const statusCard = document.getElementById('status-card');
             if(statusCard) statusCard.innerHTML = `<p style='color:red; padding:10px;'>文本10: ${error.message}</p>`;
        }
    }


    function toggleSection() {
        const content = document.getElementById('jingxi-secrets-content'); 
        const header = document.getElementById('card-header-toggle'); 
        if (!content || !header) return;

        const isExpanded = content.classList.toggle('expanded');

        if(isExpanded) {
             initDisplay();
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        initDisplay(); 

        const header = document.getElementById('card-header-toggle');
        if (header) {
             header.addEventListener('click', toggleSection);
        }
    });
</script>
</body>
</html>
